sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    // MSSCUSTODY 6459
    var assigUser = g_form.getValue('assigned_to'); //Check if the user is valid user
    var bandLmt = new GlideAjax('x_hsb11_mss_c_proc.checkBandLimit');
    bandLmt.addParam('sysparm_name', 'bandLimitCheck');
    bandLmt.addParam('sysparm_tskID', g_form.getUniqueValue());
    bandLmt.addParam('sysparm_trdID', g_form.getValue('trade_id'));
    bandLmt.addParam('sysparm_usrID', g_form.getValue('assigned_to'));
    bandLmt.addParam('sysparm_tskType', g_form.getValue('trade_task_type'));
    bandLmt.addParam('sysparm_tskOutCome', g_form.getValue('outcome'));
    bandLmt.getXMLAnswer(handleResponse);

    function handleResponse(response) {

        if (g_form.getValue('trade_id') != '') {
            if (response == 'false' && assigUser != '') {
                g_form.clearValue('assigned_to');
                //MSSCUSTODY-6598 - Defect Fix - Workspace
                if (typeof(g_aw) != 'undefined') {
                    g_modal.alert('Trade value is above checkers authorization limit.');
                } else {
                    // End of code update MSSCUSTODY-6598 - Defect Fix - Workspace
                    var gm = new GlideModal("glide_warn", true, 600);
                    gm.setTitle("Alert");
                    gm.setPreference("title", "Trade value is above checkers authorization limit");
                    gm.setPreference("onPromptComplete", function() {});
                    gm.render();

                }
            }
        }


    }


}
